/** @file
 *  @brief Provides some helper functions that check the state of debuggers for the calling
 *         process.
 */
#pragma once

#include "../../carb/Assert.h"
#include "../../carb/logging/Log.h"
#include "../../carb/process/Util.h"
#include "../../carb/Format.h"
#include "../Expected.h"

namespace omni
{
namespace extras
{

/// @{
/// Common process statuses that you may want to check

constexpr char fProcessStatusNone = '\0'; ///< Unknown/unsupported status.
constexpr char fProcessStatusRunning = 'R'; ///< Running or runnable (on run queue)
constexpr char fProcessStatusInterruptibleSleep = 'S'; ///< Interruptible sleep (waiting for an event to complete)
constexpr char fProcessStatusUninterruptibleSleep = 'D'; ///< Uninterruptible sleep (usually I/O; disk sleep)
constexpr char fProcessStatusZombie = 'Z'; ///< Zombie (terminated, parent not yet waited)
constexpr char fProcessStatusStoppedBySignal = 'T'; ///< Stopped by job control signal
constexpr char fProcessStatusStoppedByDebugger = 't'; ///< Stopped by debugger during tracing
constexpr char fProcessStatusDead = 'X'; ///< Dead (should not be seen)
constexpr char fProcessStatusWakekill = 'K'; ///< Wakekill (waking and about to be killed)
constexpr char fProcessStatusWaking = 'W'; ///< Waking (older kernels: paging)
constexpr char fProcessStatusParked = 'P'; ///< Parked
constexpr char fProcessStatusIdle = 'I'; ///< Idle (kernel thread)

/// @}

/**
 * Queries the kernel-reported status of a process.
 *
 * This is a debug helper to check for statuses like whether a process is a zombie
 * (state 'Z') or stuck in uninterruptible disk sleep (state 'D').
 *
 * @param pid The process ID to query. Use `getpid()` to query the current process.
 *
 * @return On Linux systems, returns the single-character process state.
 *         Returns '\0' if the status could not be read or parsed (including if the
 *         process does not exist). On non-Linux platforms, returns '\0'.
 * @return If an error is encountered, the string error message will be returned.
 *
 * Common state codes (kernel-dependent; see `man proc`):
 *  - 'R'  Running or runnable (on run queue)
 *  - 'S'  Interruptible sleep (waiting for an event to complete)
 *  - 'D'  Uninterruptible sleep (usually I/O; disk sleep)
 *  - 'Z'  Zombie (terminated, parent not yet waited)
 *  - 'T'  Stopped by job control signal
 *  - 't'  Stopped by debugger during tracing
 *  - 'X'  Dead (should not be seen)
 *  - 'x'  Dead (legacy/should not be seen)
 *  - 'K'  Wakekill (waking and about to be killed)
 *  - 'W'  Waking (older kernels: paging)
 *  - 'P'  Parked
 *  - 'I'  Idle (kernel thread)
 *
 * @note This function performs file I/O, so it should only be used for debugging.
 */
inline omni::expected<char, std::string> getProcessStatus([[maybe_unused]] carb::process::ProcessId pid)
{
#if CARB_PLATFORM_LINUX
    std::string statPath = carb::fmt::format("/proc/{}/stat", pid);

    FILE* statFile = fopen(statPath.c_str(), "r");
    if (!statFile)
    {
        if (errno == ENOENT)
        {
            return omni::unexpected(carb::fmt::format("file '{}' not found", statPath));
        }
        return omni::unexpected(carb::fmt::format("file '{}' could not be opened {}", statPath, errno));
    }

    char buffer[1024] = { 0 };
    if (fgets(buffer, sizeof(buffer), statFile) == NULL)
    {
        std::string error = carb::fmt::format("file '{}' could not be read {}", statPath, errno);
        fclose(statFile);
        return omni::unexpected(error);
    }
    fclose(statFile);

    // Find the state character, which follows the command in parentheses
    char* closeParen = strrchr(buffer, ')');
    if (!closeParen)
    {
        return omni::unexpected(carb::fmt::format("line '{}' from file '{}' could not be parsed", buffer, statPath));
    }

    // Skip whitespace after the closing parenthesis
    char* statePtr = closeParen + 1;
    while (*statePtr == ' ')
    {
        statePtr++;
    }

    // Check if the state is 'Z' (zombie)
    return *statePtr;
#else
    return '\0';
#endif
}


} // namespace extras
} // namespace omni
